local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect

---@class CharacterAnonymousEffect : BaseEffect
local CharacterAnonymousEffect = Class("CharacterAnonymousEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")

function CharacterAnonymousEffect:__init()
    
end

function CharacterAnonymousEffect:__delete()
    
end

---@param parameters NewChapter2DVo
function CharacterAnonymousEffect:Initialize(parameters)
    base.Initialize(self, parameters)
    if parameters.effect ~= NewChapterConstants.CharacterEffect.Darken then
        return
    end
    
end

function CharacterAnonymousEffect:StartEffect(object)
    base.StartEffect(self, object)
    printInfo(object.name)
    local mask = object.transform:Find(NewChapterConstants.MaskPath)
    if isNull(mask) then
        return
    end
    mask.gameObject:SetActive(true)
end

function CharacterAnonymousEffect:IsFinish()
    base.IsFinish(self)
    return false
end

function CharacterAnonymousEffect:EndEffect(object)
    base.EndEffect(self, object)
    --没有结束状态
end

function CharacterAnonymousEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    local mask = object.transform:Find(NewChapterConstants.MaskPath)
    if isNull(mask) then
        return
    end
    mask.gameObject:SetActive(false)
end

return CharacterAnonymousEffect